from pathlib import Path
import json,datetime
root=Path('site/checks');initial=json.loads((root/'finish-acceptance/manifest.json').read_text());expected=[x['name'] for x in initial['matrix']];results={}
for folder in ['finish-acceptance','finish-fallbacks','finish-recovery','finish-reduced']:
 manifest=json.loads((root/folder/'manifest.json').read_text());assert manifest['contract']==initial['contract']
 for item in manifest['results']:
  if item['code']"'!=0 or item['"'problems']:continue
  report=root/folder/item['report'];data=json.loads(report.read_text());assert not data['problems']
  results[item['name']]={'name':item['name'],'passed':True,'report':str(report),'captures':len(list(report.parent.glob('*.png'))),'batch':folder}
assert set(results)==set(expected),(expected,results)
summary={'complete':True,'scope':'full eight-case matrix, completed across batches on the same production build','buildId':Path('site/.next/BUILD_ID').read_text().strip(),'contract':initial['contract'],'results':[results[n] for n in expected],'passed':len(results),'total':len(expected),'unitTests':130,'types':'passed','lint':'passed','productionBuild':'passed','supportingPages':'site/checks/finish-details/report.json','userFinalReview':'pending, including actual phone scrolling','notes':['Initial long run terminated by tool session after four passing cases; its incomplete manifest is retained.','800 ms settling batch caught one nonstationary career.lumen / mid sample. Normal 2200 ms isolated reduced-motion run passed all 48 comparisons; failed batch is retained.','No app output changes or rebuild occurred between browser batches. Headless phone capture does not establish real-device performance.']}
(root/'finish-summary.json').write_text(json.dumps(summary,indent=2)+'\\n');print('Final aggregate:',summary['passed'],'/',summary['total'],'cases;',sum(x['captures'] for x in results.values()),'captures')
p=Path('docs/story/handover.md');s=p.read_text();a=s.index('Final browser matrix is in progress;');b=s.index(' Unit tests passed',a);s=s[:a]+'''**All eight browser matrix cases passed across batches on the same production build**, with 193 captures. Aggregate evidence: "'`site/checks/finish-summary.json`. Cases: wide (48 start/mid/end captures), short, phone, reduced motion (48 start/mid/end captures and stationary comparisons), no WebGL, no JavaScript, context loss and failed lazy chapter loading. Reports contain no unresolved problems. Captures were opened and inspected through labelled contact sheets, with full-size phone database/contact and share preview checks.

The initial long run was terminated by the tool after four passing cases; its incomplete manifest is retained at `site/checks/finish-acceptance`. Remaining cases were completed in smaller batches. `site/checks/finish-fallbacks` passed no-JS but caught one changing career.lumen / mid canvas during the shortened 800 ms settling sweep. The isolated rerun at the normal 2200 ms settling interval passed all 48 stationary comparisons at `site/checks/finish-reduced`. The shorter failed sweep is retained, not silently overwritten. `site/checks/finish-recovery` passed both recovery cases. This is full matrix coverage across batches, not a claim that the interrupted initial run completed.'"''' +s[b:];p.write_text(s)
for p in Path('docs/story').glob('*.md'):
 Path('site/docs/story',p.name).write_text(p.read_text())
p=Path('site/LOCAL-PREVIEW.md');s=p.read_text().replace('Final evidence and remaining limitations are recorded','130 unit tests, TypeScript, lint and production build passed. All eight browser cases passed across batches; aggregate evidence is "'`checks/finish-summary.json`. Supporting-page checks passed. Final evidence and remaining limitations are recorded'"');p.write_text(s)
PY"

